134	static void send_http(int fd, int status, const char *body)
135	{
136	    char header[192];
137	    const char *reason = status == 200 ? "OK" : status == 202 ? "Accepted" :
138	                         status == 400 ? "Bad Request" : status == 401 ? "Unauthorized" :
139	                         status == 404 ? "Not Found" :
140	                         status == 503 ? "Service Unavailable" : "Error";
141	    int length = (int)strlen(body);
142	    snprintf(header, sizeof(header),
143	             "HTTP/1.1 %d %s\r\nContent-Type: application/json\r\n"
144	             "Content-Length: %d\r\nConnection: close\r\n\r\n", status, reason, length);
145	    (void)send_all(fd, header, strlen(header));
146	    (void)send_all(fd, body, (size_t)length);
147	}
