149	static ssize_t recv_request(int fd, char *request, size_t request_size)
150	{
151	    size_t used = 0u;
152	    size_t expected = 0u;
153	    char *body;
154	
155	    while (used + 1u < request_size) {
156	        ssize_t received = recv(fd, request + used, request_size - used - 1u, 0);
157	        if (received <= 0) return received;
158	        used += (size_t)received;
159	        request[used] = '\0';
160	        body = strstr(request, "\r\n\r\n");
161	        if (body && expected == 0u) {
162	            const char *length = strstr(request, "Content-Length:");
163	            int parsed = 0;
164	            if (length) (void)sscanf(length, "Content-Length: %d", &parsed);
165	            if (parsed < 0 || (size_t)parsed > BRIDGE_BODY_MAX) return -1;
166	            expected = (size_t)(body + 4 - request) + (size_t)parsed;
167	        }
168	        if (body && used >= expected) return (ssize_t)used;
169	    }
170	    return -1;
171	}
