173	static void handle_client(smart_home_app_bridge_t *bridge, int fd)
174	{
175	    char request[BRIDGE_HEADER_MAX + BRIDGE_BODY_MAX + 1u];
176	    char method[8];
177	    char path[128];
178	    char *body;
179	    ssize_t received;
180	    smart_home_gateway_request_t api_request;
181	    smart_home_gateway_response_t api_response;
182	
183	    received = recv_request(fd, request, sizeof(request));
184	    if (received <= 0) { close(fd); return; }
185	    request[received] = '\0';
186	    if (!authorized(request, bridge->token)) {
187	        send_http(fd, 401, "{\"error\":{\"code\":\"unauthorized\"}}");
188	        close(fd);
189	        return;
190	    }
191	    if (strstr(request, "Upgrade: websocket") &&
192	        strncmp(request, "GET /v1/events ", 15) == 0) {
193	        char upgrade[512];
194	        char snapshot[SMART_HOME_GATEWAY_RESPONSE_SIZE];
195	        uint8_t frame[SMART_HOME_GATEWAY_RESPONSE_SIZE + 16u];
196	        char key[64];
197	        size_t upgrade_len;
198	        size_t frame_len;
199	        if (caddons_ws_parse_client_upgrade(request, (size_t)received, "/v1/events",
200	                                            key, sizeof(key)) != CADDONS_OK ||
201	            caddons_ws_build_server_upgrade(key, upgrade, sizeof(upgrade),
202	                                            &upgrade_len) != CADDONS_OK ||
203	            smart_home_device_service_build_snapshot_json(&bridge->app->device_service,
204	                                                           snapshot, sizeof(snapshot)) != AGENT_OK) {
205	            close(fd); return;
206	        }
207	        (void)send_all(fd, upgrade, upgrade_len);
208	        pthread_mutex_lock(&bridge->mutex);
209	        if (bridge->websocket_fd >= 0) close(bridge->websocket_fd);
210	        bridge->websocket_fd = fd;
211	        pthread_mutex_unlock(&bridge->mutex);
212	        if (caddons_ws_write_frame(CADDONS_WS_SERVER, CADDONS_WS_TEXT, snapshot,
213	                                   strlen(snapshot), NULL, frame, sizeof(frame),
214	                                   &frame_len) == CADDONS_OK) (void)send_all(fd, frame, frame_len);
215	        return;
216	    }
217	    if (sscanf(request, "%7s %127s", method, path) != 2) {
218	        send_http(fd, 400, "{\"error\":{\"code\":\"invalid_request\"}}");
219	        close(fd); return;
220	    }
221	    body = strstr(request, "\r\n\r\n");
222	    api_request.method = method;
223	    api_request.path = path;
224	    api_request.body = body ? body + 4 : "";
225	    api_request.request_id = NULL;
226	    if (smart_home_gateway_api_handle(bridge->app, &api_request, &api_response) != AGENT_OK &&
227	        api_response.status_code == 0) {
228	        api_response.status_code = 500;
229	        strcpy(api_response.body, "{\"error\":{\"code\":\"internal\"}}");
230	    }
231	    send_http(fd, api_response.status_code, api_response.body);
232	    close(fd);
233	}
